use rusqlite::{Connection, params};

use crate::error::Result;
use crate::sql::{self, query_all, query_one};
use crate::{NewUser, PasswordDigest, Role, Status, Tx, User};

// Deliberately not Debug: the code is a bearer credential.
#[derive(Clone)]
pub struct Bot {
    pub user: User,
    pub creator_id: i64,
    pub code: String,
}

impl Bot {
    pub fn create(tx: &mut Tx<'_>, creator_id: i64, name: String, password_digest: PasswordDigest) -> Result<Self> {
        let user = User::create(tx, NewUser { name, password_digest: Some(password_digest), ..Default::default() })?;
        let code = sql::base58(32);
        tx.conn().execute("INSERT INTO chat_bots (user_id, creator_id, code) VALUES (?, ?, ?)", params![user.id, creator_id, code])?;
        Ok(Self { user, creator_id, code })
    }

    pub fn find(conn: &Connection, user_id: i64) -> Result<Self> {
        let (creator_id, code) = query_one(conn, "SELECT creator_id, code FROM chat_bots WHERE user_id = ?", [user_id], |row| {
            Ok((row.get(0)?, row.get(1)?))
        })?
        .ok_or(crate::Error::RecordNotFound("Bot"))?;
        let user = User::find_active(conn, user_id)?;
        Ok(Self { user, creator_id, code })
    }

    pub fn managed_by(conn: &Connection, manager: &User) -> Result<Vec<Self>> {
        let ids: Vec<i64> = query_all(
            conn,
            "SELECT b.user_id FROM chat_bots b JOIN users u ON u.id = b.user_id WHERE u.status = 0 AND (? OR b.creator_id = ?) ORDER BY u.name, u.id",
            params![manager.role == Role::Administrator, manager.id],
            |row| row.get(0),
        )?;
        ids.into_iter().map(|id| Self::find(conn, id)).collect()
    }

    pub fn authenticate(conn: &Connection, code: &str) -> Result<Option<User>> {
        let id: Option<i64> = query_one(conn, "SELECT user_id FROM chat_bots WHERE code = ?", [code], |row| row.get(0))?;
        match id {
            Some(id) => Ok(User::find_by_id(conn, id)?.filter(|user| user.status == Status::Active)),
            None => Ok(None),
        }
    }

    pub fn can_manage(&self, manager: &User) -> bool {
        manager.role == Role::Administrator || manager.id == self.creator_id
    }

    pub fn destroy(mut self, tx: &mut Tx<'_>) -> Result<()> {
        tx.conn().execute("DELETE FROM chat_bots WHERE user_id = ?", [self.user.id])?;
        self.user.deactivate(tx)
    }
}
//! Owner/admin-scoped bot management and code-authenticated message posting.

use campfire_db::{Bot, Message, NewMessage, Room, UserChanges};
use campfire_kit::{Ctx, Error, Result, StatusCode, format, permit_keys};
use campfire_views::bots;
use ruby_compat::integer_cast;

use super::presenters;
use super::presenters::attachments::{self, Assignment, Record};
use super::presenters::page::framed_page;
use crate::app::AppCtx;
use crate::concerns::{self, Before};

async fn before(c: &mut Ctx) -> Result<()> {
    c.set_header("cache-control", "private, no-store");
    c.set_header("referrer-policy", "no-referrer");
    concerns::before_actions(c, Before::default()).await
}

pub async fn index(c: &mut Ctx) -> Result {
    before(c).await?;
    c.respond_to(&[&format::HTML])?;
    let manager = concerns::require_current_user(c)?.clone();
    let secrets = c.app().secrets.clone();
    let bots = c
        .app()
        .read(move |conn| {
            Ok(Bot::managed_by(conn, &manager)?
                .into_iter()
                .map(|bot| bots::BotSummary { user: presenters::user_summary(&secrets, &bot.user), code: bot.code })
                .collect::<Vec<_>>())
        })
        .await?;
    framed_page!(c, StatusCode::OK, |ctx| bots::Index { ctx, bots: bots.clone() }).await
}

pub async fn new(c: &mut Ctx) -> Result {
    before(c).await?;
    render_form(c, None, String::new(), false).await
}

pub async fn edit(c: &mut Ctx) -> Result {
    before(c).await?;
    let bot = managed_bot(c).await?;
    let name = bot.user.name.clone();
    render_form(c, Some(bot), name, false).await
}

async fn managed_bot(c: &Ctx) -> Result<Bot> {
    let id = c.param_str("id").and_then(integer_cast).ok_or(Error::NotFound)?;
    let bot = c.app().read(move |conn| Bot::find(conn, id)).await?;
    if !bot.can_manage(concerns::require_current_user(c)?) {
        return Err(Error::NotFound);
    }
    Ok(bot)
}

async fn render_form(c: &mut Ctx, bot: Option<Bot>, name: String, error: bool) -> Result {
    c.respond_to(&[&format::HTML])?;
    let id = bot.as_ref().map(|bot| bot.user.id);
    let avatar_url = bot.as_ref().map(|bot| presenters::avatar_path(&c.app().secrets, &bot.user));
    let status = if error { StatusCode::UNPROCESSABLE_ENTITY } else { StatusCode::OK };
    framed_page!(c, status, |ctx| bots::Form { ctx, id, name: name.clone(), avatar_url: avatar_url.clone(), error }).await
}

pub async fn create(c: &mut Ctx) -> Result {
    before(c).await?;
    save(c, None).await
}

